rawInput.command:
# unit test strategy C filter logic
$script = @'
function Normalize-PlanStatus($raw) {
  if ($null -eq $raw) { return 'unknown' }
  $s = ([string]$raw).Trim().ToLowerInvariant()
  if ([string]::IsNullOrWhiteSpace($s)) { return 'unknown' }
  if ($s -match '^(on|1|true|open|enable|enabled|active|running|投放中|开启|开)$') { return 'on' }
  if ($s -match '^(off|0|false|close|closed|disable|disabled|paused|inactive|已关闭|关闭|关|暂停)$') { return 'off' }
  return 'unknown'
}
function Test-SkipZeroDisabledCampaign($row) {
  $ps = Normalize-PlanStatus $row.planStatus
  if ($ps -ne 'off') { return $false }
  $spend = 0.0; if ($null -ne $row.spend) { $spend = [double]$row.spend }
  $revenue = 0.0; if ($null -ne $row.revenue) { $revenue = [double]$row.revenue }
  return ($spend -eq 0 -and $revenue -eq 0)
}
$cases = @(
  @{ campaign='花园拱门7/17'; planStatus='off'; spend=0; revenue=0; expect=$true },
  @{ campaign='热销品7/17'; planStatus='off'; spend=62.17; revenue=517.47; expect=$false },
  @{ campaign='全店商品7/27'; planStatus='on'; spend=14.64; revenue=45.33; expect=$false },
  @{ campaign='unknown zero'; planStatus='unknown'; spend=0; revenue=0; expect=$false }
)
foreach ($c in $cases) {
  $got = Test-SkipZeroDisabledCampaign $c
  $ok = ($got -eq $c.expect)
  Write-Host ("{0}: skip={1} expect={2} {3}" -f $c.campaign, $got, $c.expect, $(if($ok){'OK'}else{'FAIL'}))
}
'@
powershell -NoProfile -Command $script

